controller_interface::InterfaceConfiguration
CollisionControllerTorqueRelease::command_interface_configuration() const {
  controller_interface::InterfaceConfiguration config;
  config.type = controller_interface::interface_configuration_type::INDIVIDUAL;
  for (int i = 1; i <= num_joints; ++i) {
    config.names.push_back(arm_id_ + "_joint" + std::to_string(i) + "/effort");
  }
  return config;
}

controller_interface::InterfaceConfiguration
CollisionControllerTorqueRelease::state_interface_configuration() const {
  controller_interface::InterfaceConfiguration config;
  config.type = controller_interface::interface_configuration_type::INDIVIDUAL;
  for (int i = 1; i <= num_joints; ++i) {
    config.names.push_back(arm_id_ + "_joint" + std::to_string(i) + "/position");
    config.names.push_back(arm_id_ + "_joint" + std::to_string(i) + "/velocity");
  }
  for (const auto& franka_robot_model_name : franka_robot_model_->get_state_interface_names()) {
    config.names.push_back(franka_robot_model_name);
  }
  return config;
}

controller_interface::return_type CollisionControllerTorqueRelease::update(
    const rclcpp::Time& /*time*/,
    const rclcpp::Duration& /*period*/) {
  updateJointStates();
  
  const double kAlpha = 0.99;
  dq_filtered_ = (1 - kAlpha) * dq_filtered_ + kAlpha * dq_;
  Eigen::Map<const Vector7d> coriolis(franka_robot_model_->getCoriolisForceVector().data());
  
  Vector7d tau_d_calculated;

  if (trajectory_running_) {
    if (current_waypoint_index_ < trajectory_buffer_.size()) {
      auto& waypoint = trajectory_buffer_[current_waypoint_index_];
      q_d_ = waypoint.q;
      dq_d_ = waypoint.dq;
      ddq_d_ = waypoint.ddq;
      current_waypoint_index_++;
      
      // Joint Impedance with Feedforward Acceleration: tau = M * ddq_d + K*(q_d - q) + D*(dq_d - dq) + C
      auto mass_matrix_array = franka_robot_model_->getMassMatrix();
      Eigen::Map<const Eigen::Matrix<double, 7, 7>> M(mass_matrix_array.data());

      tau_d_calculated = M * ddq_d_ + k_gains_.cwiseProduct(q_d_ - q_) + d_gains_.cwiseProduct(dq_d_ - dq_filtered_) + coriolis + Friction(dq_filtered_);
    } else {
      trajectory_running_ = false;
      RCLCPP_INFO(get_node()->get_logger(), "Final position reached. Trajectory execution finished.");
      computeFrankaEffectiveMass(u_d_, true); 
      Eigen::Map<const Vector7d> q_goal_franka(franka_robot_model_->getRobotState()->q.data());

      getRobotDynamics(model_pin_, data_pin_, q_goal_franka, u_d_, true);
      tau_d_calculated = coriolis + Friction(dq_filtered_);
    }
  } else {
    tau_d_calculated = coriolis + Friction(dq_filtered_);
  }

  for (int i = 0; i < num_joints; ++i) {
    command_interfaces_[i].set_value(tau_d_calculated(i));
  }
  return controller_interface::return_type::OK;
}

CallbackReturn CollisionControllerTorqueRelease::on_init() {
  try {
    auto_declare<std::string>("arm_id", "panda");
    auto_declare<std::vector<double>>("k_gains", {});
    auto_declare<std::vector<double>>("d_gains", {});
    auto_declare<std::string>("robot_description_path", "");

    goal_service_ = get_node()->create_service<multi_mode_control_msgs::srv::JointCollisionGoal>(
        "~/joint_collision_goal",
        std::bind(&CollisionControllerTorqueRelease::goalCallback, this, std::placeholders::_1, std::placeholders::_2)
    );
  } catch (const std::exception& e) {
    fprintf(stderr, "Exception thrown during init stage with message: %s \n", e.what());
    return CallbackReturn::ERROR;
  }
  return CallbackReturn::SUCCESS;
}

CallbackReturn CollisionControllerTorqueRelease::on_configure(
    const rclcpp_lifecycle::State& /*previous_state*/) {
  arm_id_ = get_node()->get_parameter("arm_id").as_string();
  franka_robot_model_ = std::make_unique<franka_semantic_components::FrankaRobotModel>(
      franka_semantic_components::FrankaRobotModel(arm_id_ + "/robot_model",
                                                   arm_id_));
  
  // Robot Description / Pinocchio
  robot_description_path_ = get_node()->get_parameter("robot_description_path").as_string();
  if (robot_description_path_.empty()) {
    RCLCPP_FATAL(get_node()->get_logger(), "robot_description_path parameter is empty! Please provide the path to the URDF file.");
    return CallbackReturn::FAILURE;
  }

  try {
    pinocchio::urdf::buildModel(robot_description_path_, model_pin_);
    data_pin_ = pinocchio::Data(model_pin_);
    RCLCPP_INFO(get_node()->get_logger(), "Successfully loaded Pinocchio model from: %s", robot_description_path_.c_str());
  } catch (const std::exception& e) {
    RCLCPP_FATAL(get_node()->get_logger(), "Failed to load Pinocchio model from URDF: %s. Error: %s", 
                 robot_description_path_.c_str(), e.what());
    return CallbackReturn::FAILURE;
  }

  auto k_gains = get_node()->get_parameter("k_gains").as_double_array();
  auto d_gains = get_node()->get_parameter("d_gains").as_double_array();
  if (k_gains.empty()) {
    RCLCPP_FATAL(get_node()->get_logger(), "k_gains parameter not set");
    return CallbackReturn::FAILURE;
  }
  if (k_gains.size() != static_cast<uint>(num_joints)) {
    RCLCPP_FATAL(get_node()->get_logger(), "k_gains should be of size %d but is of size %ld",
                 num_joints, k_gains.size());
    return CallbackReturn::FAILURE;
  }
  if (d_gains.empty()) {
    RCLCPP_FATAL(get_node()->get_logger(), "d_gains parameter not set");
    return CallbackReturn::FAILURE;
  }
  if (d_gains.size() != static_cast<uint>(num_joints)) {
    RCLCPP_FATAL(get_node()->get_logger(), "d_gains should be of size %d but is of size %ld",
                 num_joints, d_gains.size());
    return CallbackReturn::FAILURE;
  }
  for (int i = 0; i < num_joints; ++i) {
    d_gains_(i) = d_gains.at(i);
    k_gains_(i) = k_gains.at(i);
  }
  dq_filtered_.setZero();

  return CallbackReturn::SUCCESS;
}

CallbackReturn CollisionControllerTorqueRelease::on_activate(
    const rclcpp_lifecycle::State& /*previous_state*/) {
  updateJointStates();
  franka_robot_model_->assign_loaned_state_interfaces(state_interfaces_);
  q_d_ = q_;
  dq_d_.setZero();
  ddq_d_.setZero();
  trajectory_running_ = false;
  return CallbackReturn::SUCCESS;
}

void CollisionControllerTorqueRelease::updateJointStates() {
  for (auto i = 0; i < num_joints; ++i) {
    const auto& position_interface = state_interfaces_.at(2 * i);
    const auto& velocity_interface = state_interfaces_.at(2 * i + 1);

    assert(position_interface.get_interface_name() == "position");
    assert(velocity_interface.get_interface_name() == "velocity");

    q_(i) = position_interface.get_value();
    dq_(i) = velocity_interface.get_value();
  }
}

void CollisionControllerTorqueRelease::goalCallback(
    const std::shared_ptr<multi_mode_control_msgs::srv::JointCollisionGoal::Request> request,
    std::shared_ptr<multi_mode_control_msgs::srv::JointCollisionGoal::Response> response) {
  
  if (trajectory_running_) {
    response->success = false;
    response->message = "A trajectory is already in execution.";
    return;
  }

  ruckig::InputParameter<7> ruckig_input;
  for (int i = 0; i < num_joints; ++i) {
    ruckig_input.current_position[i] = q_(i);
    ruckig_input.current_velocity[i] = 0.0;
    ruckig_input.current_acceleration[i] = 0.0;

    ruckig_input.target_position[i] = request->q[i];
    ruckig_input.target_velocity[i] = request->dq[i];
    ruckig_input.target_acceleration[i] = request->qdd[i];

    ruckig_input.max_velocity[i] = (request->max_velocity[i] > 0.0) ? request->max_velocity[i] : 2.0;
    ruckig_input.max_acceleration[i] = (request->max_acceleration[i] > 0.0) ? request->max_acceleration[i] : 1.0;
    ruckig_input.max_jerk[i] = (request->max_jerk[i] > 0.0) ? request->max_jerk[i] : 10.0;
  }

  if (request->duration > 0.0) {
      ruckig_input.minimum_duration = request->duration;
      ruckig_input.duration_discretization = ruckig::DurationDiscretization::Continuous;
  }

  ruckig::Trajectory<7> trajectory;
  auto result = otg_.calculate(ruckig_input, trajectory);
  
  if (result == ruckig::Result::Working || result == ruckig::Result::Finished) {
      // Impact direction u from request
      u_d_ << request->u[0], request->u[1], request->u[2];
      if (u_d_.norm() < 1e-6) {
          u_d_ << 1.0, 0.0, 0.0; // Default as requested
      } else {
          u_d_.normalize(); // Ensure it's a unit vector
      }

      // 1. Comparison at CURRENT configuration
      Eigen::VectorXd q_curr = q_;


      // 2. Computation at TARGET configuration
      Eigen::VectorXd q_goal(7);
      for (int i = 0; i < 7; ++i) q_goal(i) = request->q[i];

      RCLCPP_INFO(get_node()->get_logger(), "Pinocchio TARGET computation:");
      auto pin_goal = getRobotDynamics(model_pin_, data_pin_, q_goal, u_d_, true);
      RCLCPP_INFO(get_node()->get_logger(), "--------------------------------------------------");


      // 3. Trajectory computation
      trajectory_buffer_.clear();
      double duration = trajectory.get_duration();
      // Sample at 1kHz
      std::array<double, 7> q_sample;
      std::array<double, 7> dq_sample;
      std::array<double, 7> ddq_sample;
      for (double t = 0.001; t < duration; t += 0.001) {
          Waypoint wp;
          trajectory.at_time(t, q_sample, dq_sample, ddq_sample);
          for(int i=0; i<7; ++i) { 
              wp.q(i) = q_sample[i]; 
              wp.dq(i) = dq_sample[i]; 
              wp.ddq(i) = ddq_sample[i];
          }
          trajectory_buffer_.push_back(wp);
      }
      // Ensure the final point is included
      Waypoint final_wp;
      trajectory.at_time(duration, q_sample, dq_sample, ddq_sample);
      for(int i=0; i<7; ++i) { 
          final_wp.q(i) = q_sample[i]; 
          final_wp.dq(i) = dq_sample[i]; 
          final_wp.ddq(i) = ddq_sample[i];
      }
      trajectory_buffer_.push_back(final_wp);

      RCLCPP_INFO(get_node()->get_logger(), "Trajectory generated. Requested duration: %.3f, Ruckig duration: %.3f, Waypoints: %ld", 
                  request->duration, duration, trajectory_buffer_.size());

      current_waypoint_index_ = 0;
      trajectory_running_ = true;
      response->success = true;
      response->message = "Trajectory generated and execution started.";
  } else {
      response->success = false;
      response->message = "Failed to generate trajectory.";
  }
}

CollisionControllerTorqueRelease::RobotDynamics CollisionControllerTorqueRelease::getRobotDynamics(
    const pinocchio::Model& model, pinocchio::Data& data, const Eigen::VectorXd& q, const Eigen::Vector3d& u, bool verbose) {
  
  RobotDynamics results;
  
  // 1. Mass Matrix
  pinocchio::crba(model, data, q);
  data.M.triangularView<Eigen::StrictlyLower>() = data.M.transpose().triangularView<Eigen::StrictlyLower>();
  results.M = data.M;

  // 2. Jacobian (at EE)
  auto frame_id = model.getFrameId("panda_link8");
  if (frame_id >= model.frames.size()) {
      frame_id = model.frames.size() - 1;
  }
  results.J.setZero();
  pinocchio::computeFrameJacobian(model, data, q, frame_id, pinocchio::ReferenceFrame::LOCAL_WORLD_ALIGNED, results.J);
  
  // 3. Reflected/Effective Mass (Mobility Matrix):
  // Version 1: Direct Inverse (reference)
  Eigen::Matrix<double, 6, 6> JMJt_inv = results.J * (results.M.inverse()) * results.J.transpose();
  
  // Version 2: Cholesky (stable)
  Eigen::Matrix<double, 6, 6> JMJt_chol = results.J * results.M.llt().solve(results.J.transpose());
  results.Lambda = JMJt_chol;

  // 4. Scalar Effective Mass:
  Eigen::Matrix3d Lambda_pos = results.Lambda.block<3, 3>(0, 0);
  results.m_eff = 1.0 / (u.transpose() * Lambda_pos * u);

  // 5. Comparison printed in verbose mode
  if (verbose) {
    std::stringstream ss_m, ss_j, ss_l;
    ss_m << results.M;
    ss_j << results.J;
    ss_l << results.Lambda;
    RCLCPP_INFO(get_node()->get_logger(), "Mass Matrix:\n%s", ss_m.str().c_str());
    RCLCPP_INFO(get_node()->get_logger(), "Geometric Jacobian:\n%s", ss_j.str().c_str());
    RCLCPP_INFO(get_node()->get_logger(), "Reflected Mass J*M⁻1*J^T:\n%s", ss_l.str().c_str());
    
    double m_eff_inv = 1.0 / (u.transpose() * JMJt_inv.block<3,3>(0,0) * u);
    RCLCPP_INFO(get_node()->get_logger(), "Scalar Effective Mass (Inverse): %.4f", m_eff_inv);
    RCLCPP_INFO(get_node()->get_logger(), "Scalar Effective Mass (Cholesky): %.4f", results.m_eff);
  }

  return results;
}

double CollisionControllerTorqueRelease::computeFrankaEffectiveMass(const Eigen::Vector3d& u, bool verbose) {
  auto mass_array = franka_robot_model_->getMassMatrix();
  auto jacobian_array = franka_robot_model_->getZeroJacobian(franka::Frame::kEndEffector);
  
  Eigen::Map<const Eigen::Matrix<double, 7, 7>> M(mass_array.data());
  Eigen::Map<const Eigen::Matrix<double, 6, 7>> J(jacobian_array.data());
  
  // Lambda = (J * M⁻1 * J^T)
  // Version 1: Direct Inverse
  Eigen::Matrix<double, 6, 6> JMJt_inv = J * (M.inverse()) * J.transpose();

  // Version 2: Cholesky
  Eigen::Matrix<double, 6, 6> JMJt_chol = J * M.llt().solve(J.transpose());
  Eigen::Matrix<double, 6, 6> Lambda = JMJt_chol;

  // Scalar Effective Mass: 
  double m_eff_inv = 1.0 / (u.transpose() * (JMJt_inv.block<3,3>(0,0)) * u);
  double m_eff_chol = 1.0 / (u.transpose() * (Lambda.block<3,3>(0,0)) * u);

  // Version 3: Gaz et al. (2019) analytical mass matrix + Franka Jacobian (Cholesky)
  Vector7d q_current;
  const auto& q_arr = franka_robot_model_->getRobotState()->q;
  for (int i = 0; i < 7; ++i) q_current(i) = q_arr[i];
  Eigen::Matrix<double, 7, 7> M_gaz = MassMatrix(q_current);
  Eigen::Matrix<double, 6, 6> JMJt_gaz = J * M_gaz.llt().solve(J.transpose());
  double m_eff_gaz = 1.0 / (u.transpose() * (JMJt_gaz.block<3,3>(0,0)) * u);

  if (verbose) {
    std::stringstream ss_m, ss_j;
    ss_m << M;
    ss_j << J;
    RCLCPP_INFO(get_node()->get_logger(), "--------------------------------------------------");
    RCLCPP_INFO(get_node()->get_logger(), "Effective Mass Comparison (at ACTUAL configuration):");
    RCLCPP_INFO(get_node()->get_logger(), "Franka Mass Matrix:\n%s", ss_m.str().c_str());
    RCLCPP_INFO(get_node()->get_logger(), "Franka Jacobian (EE):\n%s", ss_j.str().c_str());
    RCLCPP_INFO(get_node()->get_logger(), "Scalar Effective Mass [Franka M, Direct Inverse]:  %.4f kg", m_eff_inv);
    RCLCPP_INFO(get_node()->get_logger(), "Scalar Effective Mass [Franka M, Cholesky]:        %.4f kg", m_eff_chol);
    RCLCPP_INFO(get_node()->get_logger(), "Scalar Effective Mass [Gaz 2019 M, Cholesky]:      %.4f kg", m_eff_gaz);

    // Kinetic energy T = 0.5 * dq^T * M * dq  for three test velocity vectors
    Vector7d dq1; dq1 << 1, 0,  0, 0, 0, 0, 0;
    Vector7d dq2; dq2 << 1, 0,  1, 0, 0, 0, 0;
    Vector7d dq3; dq3 << 1, 0, -1, 0, 0, 0, 0;
    double T1 = 0.5 * dq1.transpose() * M * dq1;
    double T2 = 0.5 * dq2.transpose() * M * dq2;
    double T3 = 0.5 * dq3.transpose() * M * dq3;
    RCLCPP_INFO(get_node()->get_logger(), "Kinetic Energy T = 0.5*dq^T*M*dq (Franka M):");
    RCLCPP_INFO(get_node()->get_logger(), "  dq=[1,0, 0,0,0,0,0] -> T = %.6f J", T1);
    RCLCPP_INFO(get_node()->get_logger(), "  dq=[1,0, 1,0,0,0,0] -> T = %.6f J", T2);
    RCLCPP_INFO(get_node()->get_logger(), "  dq=[1,0,-1,0,0,0,0] -> T = %.6f J", T3);
    RCLCPP_INFO(get_node()->get_logger(), "--------------------------------------------------");
  }
  return m_eff_chol;
}

